  v_ws_id    UUID;
  v_proj_id  UUID;
  v_ord      INT;
  v_mk       TEXT;
  v_dt       TEXT;
  v_pd       DATE;
BEGIN
  SELECT id INTO v_org_id FROM organizations WHERE slug = 'config-seed-org' LIMIT 1;
