    INSERT INTO organizations (id, name, slug)
    VALUES (uuid_generate_v4(), 'Config Import Org', 'config-seed-org')
    RETURNING id INTO v_org_id;
  END IF;
  SELECT id INTO v_user_id FROM users LIMIT 1;
