    INSERT INTO users (id, auth0_id, email, display_name)
    VALUES (uuid_generate_v4(), 'seed|config-import', 'config-import@local.dev', 'Config Import')
    RETURNING id INTO v_user_id;
  END IF;

  SELECT id INTO v_ws_id FROM workspaces WHERE org_id = v_org_id AND slug = 'config' LIMIT 1;
  IF v_ws_id IS NULL THEN
    INSERT INTO workspaces (id, org_id, name, slug, created_by, workflow_definition, settings)
    VALUES (uuid_generate_v4(), v_org_id, 'OneHouse Upgrade Program Roadmap Dashboard', 'config', v_user_id, '[{"type":"state","key":"NS","short":"NST","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"START","short":"GO","title":"Start","subtitle":"Project Kickoff"},{"type":"state","key":"DEV","short":"DEV","title":"Development","description":"In development"},{"type":"milestone","key":"M0","short":"M0","title":"Dev Complete","subtitle":"Development Finished"},{"type":"state","key":"VAL","short":"VAL","title":"Validation","description":"Under Technical Validation"},{"type":"milestone","key":"M1","short":"M1","title":"Val Complete","subtitle":"Validation Done"},{"type":"state","key":"ACC","short":"ACC","title":"Acceptance","description":"Acceptance Testing"},{"type":"milestone","key":"M2","short":"M2","title":"Production Ready","subtitle":"Ready for DTU consumption"},{"type":"state","key":"PRD","short":"PRD","title":"Parallel Run","description":"Parallel run 1.0 & 2.0"},{"type":"milestone","key":"M3","short":"M3","title":"Switch Complete","subtitle":"OneSource 1.0 Switch"},{"type":"state","key":"FIN","short":"FIN","title":"Finished","description":"Upgrade Completed"}]'::jsonb, '{"start_month":"01/2026","end_month":"12/2026","group_order":["OneSource 2.0","CDS Transversal","CDS Commercial","CDS SF","CDS D2D","Finance PLE Upgrade","SPC/SPO PLE Upgrade","AMEA-CNAO Upgrade"]}'::jsonb)
    RETURNING id INTO v_ws_id;
  ELSE
    UPDATE workspaces SET workflow_definition = '[{"type":"state","key":"NS","short":"NST","title":"Not Started","description":"Not yet started"},{"type":"milestone","key":"START","short":"GO","title":"Start","subtitle":"Project Kickoff"},{"type":"state","key":"DEV","short":"DEV","title":"Development","description":"In development"},{"type":"milestone","key":"M0","short":"M0","title":"Dev Complete","subtitle":"Development Finished"},{"type":"state","key":"VAL","short":"VAL","title":"Validation","description":"Under Technical Validation"},{"type":"milestone","key":"M1","short":"M1","title":"Val Complete","subtitle":"Validation Done"},{"type":"state","key":"ACC","short":"ACC","title":"Acceptance","description":"Acceptance Testing"},{"type":"milestone","key":"M2","short":"M2","title":"Production Ready","subtitle":"Ready for DTU consumption"},{"type":"state","key":"PRD","short":"PRD","title":"Parallel Run","description":"Parallel run 1.0 & 2.0"},{"type":"milestone","key":"M3","short":"M3","title":"Switch Complete","subtitle":"OneSource 1.0 Switch"},{"type":"state","key":"FIN","short":"FIN","title":"Finished","description":"Upgrade Completed"}]'::jsonb, settings = '{"start_month":"01/2026","end_month":"12/2026","group_order":["OneSource 2.0","CDS Transversal","CDS Commercial","CDS SF","CDS D2D","Finance PLE Upgrade","SPC/SPO PLE Upgrade","AMEA-CNAO Upgrade"]}'::jsonb WHERE id = v_ws_id;
