    INSERT INTO milestones (project_id, org_id, milestone_key, planned_date, status)
    VALUES (v_proj_id, v_org_id, v_mk, v_pd, 'planned')
    ON CONFLICT (project_id, milestone_key) DO UPDATE SET planned_date = EXCLUDED.planned_date;
    v_mk := 'LIVE'; v_dt := '20/07/2027'; v_pd := TO_DATE(v_dt, 'DD/MM/YYYY');
    INSERT INTO milestones (project_id, org_id, milestone_key, planned_date, status)
    VALUES (v_proj_id, v_org_id, v_mk, v_pd, 'planned')
    ON CONFLICT (project_id, milestone_key) DO UPDATE SET planned_date = EXCLUDED.planned_date;
  END IF;


  -- Add all existing users to the seed org so they can see seeded workspaces
  INSERT INTO org_members (org_id, user_id, role)
  SELECT v_org_id, u.id, 'admin' FROM users u
  ON CONFLICT (org_id, user_id) DO NOTHING;

END $$;
